import java.util.*; public class PrimAlgorithm { static class Edge { int to, weight; Edge(int to, int weight) { this.to = to; this.weight = weight; } } public int primMST(int n, List<List<Edge>> adj) { boolean[] visited = new boolean[n]; PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1])); pq.add(new int[]{0, 0}); int mstWeight = 0; int edgesCount = 0; while (!pq.isEmpty() && edgesCount < n) { int[] curr = pq.poll(); int u = curr[0]; int w = curr[1]; if (visited[u]) continue; visited[u] = true; mstWeight += w; edgesCount++; for (Edge edge : adj.get(u)) { if (!visited[edge.to]) { pq.add(new int[]{edge.to, edge.weight}); } } } return mstWeight; } }
